<template><ContentWrap><el-row :gutter="16"><el-col v-for="card in cards" :key="card.label" :span="6"><el-card><div class="label">{{card.label}}</div><div class="value" :style="{color:card.color}">{{card.value}}</div></el-card></el-col></el-row></ContentWrap><ContentWrap><el-button type="primary" :loading="checking" @click="checkAll">检测全部</el-button><el-table v-loading="loading" :data="list" class="mt-15px"><el-table-column label="服务器" prop="name"/><el-table-column label="地址" prop="host"/><el-table-column label="状态"><template #default="s"><el-tag :type="types[s.row.healthStatus]">{{texts[s.row.healthStatus]}}</el-tag></template></el-table-column><el-table-column label="最后检测" prop="lastCheckTime" :formatter="dateFormatter"/><el-table-column label="错误" prop="lastError" show-overflow-tooltip/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="checkOne(s.row.id)">立即检测</el-button></template></el-table-column></el-table></ContentWrap></template>
<script setup lang="ts">import {dateFormatter} from '@/utils/formatTime';import * as Api from '@/api/xray/server';defineOptions({name:'XrayStatus'});const loading=ref(false),checking=ref(false),list=ref<any[]>([]);const texts=['未检测','正常','服务停止','不可达'];const types:any[]=['info','success','warning','danger'];const cards=computed(()=>[{label:'服务器总数',value:list.value.length,color:'#409eff'},{label:'运行正常',value:list.value.filter(x=>x.healthStatus===1).length,color:'#67c23a'},{label:'运行异常',value:list.value.filter(x=>x.healthStatus===2||x.healthStatus===3).length,color:'#f56c6c'},{label:'尚未检测',value:list.value.filter(x=>!x.healthStatus).length,color:'#909399'}]);const load=async()=>{loading.value=true;try{const r=await Api.getServerPage({pageNo:1,pageSize:100});list.value=r.list}finally{loading.value=false}};const checkOne=async(id:number)=>{await Api.checkHealth(id);await load()};const checkAll=async()=>{checking.value=true;try{await Promise.allSettled(list.value.map(x=>Api.checkHealth(x.id)));await load()}finally{checking.value=false}};onMounted(load);</script><style scoped>.label{color:var(--el-text-color-secondary)}.value{font-size:30px;font-weight:600;margin-top:12px}</style>
